import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tanh_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor tanh_forward(torch::Tensor x);
"""

tanh_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Fast tanh using fast-math intrinsics, clamped for numerical stability.
__device__ __forceinline__ float fast_tanhf(float x)
{
  // tanh(x) = (e^{2x} - 1) / (e^{2x} + 1); tanh saturates to +/-1 for |x| > ~9.
  const float xc = fminf(fmaxf(x, -10.0f), 10.0f);
  const float e = __expf(2.0f * xc);
  return __fdividef(e - 1.0f, e + 1.0f);
}
template <int Threads, int Vec>
__global__ void tanh_kernel_cute(const float* __restrict__ X,
                                 float* __restrict__ Y,
                                 int64_t N,
                                 int64_t N4,
                                 int rem)
{
  // Vectorized view over float4 elements using CuTe tensors.
  Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X)),
                           make_shape(N4));
  Tensor mY4 = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(Y)),
                           make_shape(N4));

  const int tid = threadIdx.x;
  const int64_t stride = (int64_t)gridDim.x * Threads;
  int64_t idx = (int64_t)blockIdx.x * Threads + tid;
  // Grid-stride loop on a persistent, device-sized grid: every iteration
  // processes Vec independent float4 elements per thread, issuing all loads
  // back-to-back to maximize memory-level parallelism, while keeping each SM
  // busy until the work drains (no per-block tail waves / load imbalance).
  const int64_t step = (int64_t)Vec * stride;
  while (idx + (Vec - 1) * stride < N4) {
    float4 v[Vec];
    #pragma unroll
    for (int i = 0; i < Vec; ++i) {
      v[i] = mX4(idx + i * stride);
    }
    #pragma unroll
    for (int i = 0; i < Vec; ++i) {
      v[i].x = fast_tanhf(v[i].x);
      v[i].y = fast_tanhf(v[i].y);
      v[i].z = fast_tanhf(v[i].z);
      v[i].w = fast_tanhf(v[i].w);
    }
    #pragma unroll
    for (int i = 0; i < Vec; ++i) {
      mY4(idx + i * stride) = v[i];
    }
    idx += step;
  }
  // Remaining whole float4 elements that do not fill a complete Vec batch.
  while (idx < N4) {
    float4 v = mX4(idx);
    v.x = fast_tanhf(v.x);
    v.y = fast_tanhf(v.y);
    v.z = fast_tanhf(v.z);
    v.w = fast_tanhf(v.w);
    mY4(idx) = v;
    idx += stride;
  }
  // Scalar tail: rem < 4 elements, handled entirely by block 0.
  if (blockIdx.x == 0 && rem > 0) {
    Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N));
    Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N));
    for (int r = tid; r < rem; r += Threads) {
      const int64_t idx = N4 * 4 + r;
      mY(idx) = fast_tanhf(mX(idx));
    }
  }
}

torch::Tensor tanh_forward(torch::Tensor x)
{
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  const int64_t N = x_c.numel();
  if (N == 0) {
    return y;
  }

  const float* X = x_c.data_ptr<float>();
  float* Y = y.data_ptr<float>();

  constexpr int Threads = 512;
  constexpr int Vec = 4;

  const int64_t N4 = N / 4;
  const int rem = (int)(N - N4 * 4);
  // Persistent grid-stride sizing: query real per-SM residency and launch an
  // exact whole number of waves so this memory-bound kernel has no partial-wave tail.
  int num_sms = 0;
  cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount,
                         (int)x_c.get_device());
  if (num_sms < 1) num_sms = 1;
  const int64_t tile = (int64_t)Threads * Vec;
  int blocks_per_sm = 0;
  const cudaError_t occ_err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
      &blocks_per_sm, tanh_kernel_cute<Threads, Vec>, Threads, 0);
  if (occ_err != cudaSuccess || blocks_per_sm < 1) {
    (void)cudaGetLastError();
    blocks_per_sm = 2048 / Threads;
  }
  const int64_t fill_grid = (int64_t)num_sms * blocks_per_sm;
  const int64_t work_grid = N4 > 0 ? (N4 + tile - 1) / tile : 1;
  const int64_t grid = fill_grid < work_grid ? fill_grid : work_grid;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  tanh_kernel_cute<Threads, Vec><<<(unsigned)grid, Threads, 0, stream>>>(
      X, Y, N, N4, rem);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "tanh_kernel_cute launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=tanh_cpp_decl,
    cuda_sources=tanh_cuda_src,
    functions=["tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Tanh activation implemented with a single custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.tanh_forward(x)

